package auth

import (
	"errors"
	"strings"
	"testing"

	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/ui/components"
)

// The router posts its messages (ctx new, MCP) with components.PostFooter. The
// auth view is where a new context lands, so it has to hold a FooterMessage
// like every other view (Rule 128). The expiry is built by hand instead of
// running the Cmd: tea.Tick really sleeps.

// footerInfoLine returns the last line of RenderFooter, the info line.
func footerInfoLine(m *Model, width int) string {
	lines := strings.Split(m.RenderFooter(width), "\n")
	return lines[len(lines)-1]
}

func TestPostFooterMsgAppearsCenteredInTheFooter(t *testing.T) {
	cases := []struct {
		name  string
		level components.Level
		text  string
	}{
		{"info", components.LevelInfo, `Context "staging" created`},
		{"warning", components.LevelWarning, "Context already active"},
		{"error", components.LevelError, "Could not switch context"},
	}
	for i, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			m := newTestModel(t, testConfig(), newFakeStorage())
			const width = 100

			m = feed(t, m, components.PostFooterMsg{ID: uint64(9000 + i), Level: tc.level, Text: tc.text})

			line := footerInfoLine(m, width)
			if !strings.Contains(line, tc.text) {
				t.Fatalf("info line = %q, want it to carry %q", line, tc.text)
			}
			if got := lipgloss.Width(line); got != width {
				t.Errorf("info line width = %d, want the full %d", got, width)
			}
			plain := ansi.Strip(line)
			lead := len(plain) - len(strings.TrimLeft(plain, " "))
			trail := len(plain) - len(strings.TrimRight(plain, " "))
			if lead == 0 || lead-trail > 1 || trail-lead > 1 {
				t.Errorf("message not centered: %d leading, %d trailing cells", lead, trail)
			}
		})
	}
}

func TestPostedFooterMessageExpires(t *testing.T) {
	m := newTestModel(t, testConfig(), newFakeStorage())
	const id = 9100

	m = feed(t, m, components.PostFooterMsg{ID: id, Level: components.LevelInfo, Text: "Context \"x\" created"})
	if !strings.Contains(m.RenderFooter(100), "created") {
		t.Fatal("message not shown before its expiry")
	}

	// A stale expiry (another message's timer) leaves it alone.
	m = feed(t, m, components.ClearFooterMsg{ID: id + 1})
	if !strings.Contains(m.RenderFooter(100), "created") {
		t.Error("a stale ClearFooterMsg removed the message")
	}

	m = feed(t, m, components.ClearFooterMsg{ID: id})
	if strings.Contains(m.RenderFooter(100), "created") {
		t.Error("message still shown after its ClearFooterMsg")
	}
}

func TestFooterHeightIsUnchangedWithAMessage(t *testing.T) {
	m := newTestModel(t, testConfig(), newFakeStorage())
	want := m.GetFooterHeight()
	if want != 2 {
		t.Fatalf("GetFooterHeight() = %d, want 2 (blank line + info line)", want)
	}

	m = feed(t, m, components.PostFooterMsg{ID: 9200, Level: components.LevelWarning, Text: "something to read"})

	if got := m.GetFooterHeight(); got != want {
		t.Errorf("GetFooterHeight() = %d with a message, want %d", got, want)
	}
	if got := strings.Count(m.RenderFooter(100), "\n") + 1; got != want {
		t.Errorf("RenderFooter() emitted %d lines with a message, want %d", got, want)
	}
	if !strings.Contains(footerInfoLine(m, 100), "something to read") {
		t.Error("message is not on the info line (the last one)")
	}
}

// With no message posted, the view's own states keep showing and the footer
// stays two blank-looking lines.
func TestAuthStatesStillShowWithoutAFooterMessage(t *testing.T) {
	m := newTestModel(t, testConfig(), newFakeStorage())
	m = feed(t, m, AuthResultMsg{Error: errors.New("401 unauthorized")})

	if !strings.Contains(m.Render(), "401 unauthorized") {
		t.Error("View() lost the authentication error")
	}
	footer := ansi.Strip(m.RenderFooter(100))
	if strings.TrimSpace(footer) != "" {
		t.Errorf("footer = %q, want no text when nothing was posted", footer)
	}
	if got := strings.Count(m.RenderFooter(100), "\n") + 1; got != m.GetFooterHeight() {
		t.Errorf("RenderFooter() emitted %d lines, GetFooterHeight() = %d", got, m.GetFooterHeight())
	}
}

package auth

import (
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

func (m Model) InEditMode() bool {
	// In edit mode only if a textinput has focus
	// and the user is not currently authenticating
	// If authenticated, we are no longer in edit mode
	if m.authenticated || m.authenticating {
		return false
	}
	// In edit mode if we're on one of the text fields
	return m.currentField == fieldToken
}

func (m Model) GetShortcuts() shortcut.Shortcuts {
	return []shortcut.Shortcut{
		{Key: "enter", Description: "Submit / Advance field"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight returns the footer height for this view (Rule 124).
func (m Model) GetFooterHeight() int {
	return 2 // empty line + info line
}

// RenderFooter returns the footer content rendered below the viewport (Rule 124).
func (m Model) RenderFooter(width int) string {
	return theme.EmptyLineBg(width) + "\n" + m.footer.View(width, components.Status{})
}

// vocab is the wording of the forge this context targets. Resolved from the
// config rather than carried on shared.State: the title and the help are needed
// before any session exists, so a value hanging off a live Forge would be
// unavailable exactly where it is needed most.
func (m Model) vocab() forge.Vocabulary {
	if m.config == nil {
		return forge.VocabularyFor("")
	}
	return forge.VocabularyFor(m.config.Forge.Type)
}

func (m Model) GetTitle() string {
	forgeType := ""
	if m.config != nil {
		forgeType = m.config.Forge.Type
	}
	return theme.ForgeIcon(forgeType) + " " + m.vocab().Name + " Authentication"
}

func (m Model) GetIcon() string {
	return ""
}

// GetHeaderInfo returns the key-value info for the header
func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	return []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
	}
}

// GetHelpContent returns the help content for the GitLab Auth view
func (m Model) GetHelpContent() help.Content {
	v := m.vocab()
	return help.Content{
		Title: v.Name + " Authentication",
		Description: "This view allows you to connect to a " + v.Name + " instance. Once authenticated, you can explore " +
			strings.ToLower(v.Namespaces) + " and " + strings.ToLower(v.Repositories) +
			", clone repositories, and manage your " + v.Name + " resources.",
		KeyBindings: []help.KeyBinding{
			{Key: "↑ / ↓", Description: "Navigate between form fields"},
			{Key: "enter", Description: "Submit form / advance to next field"},
			{Key: "ctrl+p", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Where the token is stored",
				Body: "The token goes to the host's own secret manager — the Windows Credential Manager, the macOS Keychain, or a Secret Service implementation on Linux. It is never written to a configuration file.\n\n" +
					"When no such store answers, DevDesk falls back to git's credential helper, provided git is configured with one that does not itself write plaintext. Failing that, the token is kept for this session only and you will be asked for it again next launch — the view says so when that happens.\n\n" +
					"Set app.secret_backend in the context configuration to \"keyring\" or \"git-credential\" to pin one of them instead of letting DevDesk choose.",
			},
			{
				Title: v.TokenLabel,
				// The prefix is a hint, never a check: DevDesk does not validate
				// it, and saying "must" about something nothing enforces is how
				// a user comes to believe a working token is broken.
				Body: v.TokenHelp + " Tokens look like " + v.TokenPlaceholder + ".",
			},
		},
	}
}

// View is the Bubble Tea v2 face of Render: the content only. The terminal
// state (alternate screen, colours) belongs to whoever owns the program.
func (m *Model) View() tea.View { return tea.NewView(m.Render()) }

// Render renders the view
func (m *Model) Render() string {
	var sections []string

	// Status (only show when not authenticated, to avoid duplication with logged-in view)
	if m.success != "" && !m.authenticated {
		sections = append(sections, m.renderSuccess())
	}

	// Warning (non-blocking, e.g. credentials save failure)
	if m.warning != "" {
		sections = append(sections, m.renderWarning())
	}

	// What the migration off the config file did, if anything
	if len(m.notices) > 0 {
		sections = append(sections, m.renderNotices())
	}

	// Form
	sections = append(sections, m.renderForm())

	// Error
	if m.error != "" {
		sections = append(sections, m.renderError())
	}

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1).Render(strings.Join(sections, "\n"))
}

func (m *Model) renderForm() string {
	var b strings.Builder

	// Spinner if authentication is in progress
	if m.authenticating {
		b.WriteString(theme.SpinnerMessage(m.spinner.View(), "Authenticating...") + "\n\n")
		return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
	}

	// If authenticated, show the "Logged in" view
	if m.authenticated {
		return m.renderLoggedInView()
	}

	// The URL is shown, not edited: it is configuration, and the configuration
	// view owns it. Both views used to write it, so neither was authoritative.
	b.WriteString(m.renderConfiguredURL() + "\n\n")

	// Token
	labelStyle := lipgloss.NewStyle().Background(theme.ColorBackground).Bold(true)
	if m.currentField == fieldToken {
		labelStyle = labelStyle.Foreground(theme.ColorPrimary)
	}
	b.WriteString(labelStyle.Render("Personal Access Token") + "\n")
	b.WriteString(m.tokenInput.View() + "\n\n")

	// Token destination. It isn't a choice — it's the only path — but the
	// user must be able to read where their secret is going, and above all
	// notice when nothing is being saved (§3.9).
	b.WriteString(m.renderSecretDestination() + "\n\n")

	// Button
	b.WriteString(theme.RenderButton("Login", m.currentField == fieldSubmit, "primary"))

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
}

// renderSecretDestination names the store the token goes to, or warns that
// there is none. The warning is deliberately the louder of the two.
func (m *Model) renderSecretDestination() string {
	if m.secrets.Persists() {
		return theme.DimStyle.Render(m.secrets.Detail)
	}
	return lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorWarn).
		Render(theme.IconWarning + " " + m.secrets.Detail)
}

// renderNotices reports what the migration off plaintext configuration did.
// Empty in every normal run — it only has something to say the first time a
// user launches a build that no longer keeps secrets in config.yaml.
func (m *Model) renderNotices() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorHighlight).
		Padding(1, 2)
	return style.Render(theme.IconLock + " " + strings.Join(m.notices, "\n  "))
}

func (m *Model) renderLoggedInView() string {
	var b strings.Builder

	// Show the user's info
	b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Bold(true).Render("Authenticated as: "))
	b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorPrimary).Bold(true).Render(m.user.Username))
	if m.user.Name != "" {
		b.WriteString(theme.Bg(" (" + m.user.Name + ")"))
	}
	b.WriteString("\n")

	// Show the forge's URL
	if m.config != nil && m.config.Forge.URL != "" {
		b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText).Bold(true).Render(m.vocab().Name + " URL: "))
		b.WriteString(lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorPrimary).Bold(true).Render(m.config.Forge.URL) + "\n")
	}
	b.WriteString("\n")

	// Logout button
	b.WriteString(theme.RenderButton("Logout", m.currentField == fieldToken, "danger"))

	return lipgloss.NewStyle().Background(theme.ColorBackground).Padding(1, 2).Render(b.String())
}

func (m *Model) renderSuccess() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorOK).
		Padding(1, 2)
	return style.Render(m.success)
}

func (m *Model) renderWarning() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorError).
		Padding(1, 2).
		Width(m.width - 8)
	return style.Render(theme.IconWarning + " " + m.warning)
}

func (m *Model) renderError() string {
	style := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorError).
		Padding(1, 2)
	return style.Render("✗ " + m.error)
}

// renderConfiguredURL shows the server this view will authenticate against, and
// says where to change it. Empty is the case worth naming: without a URL there
// is nothing to log into, and the user would otherwise be told the token is
// missing for a problem that is not the token.
func (m Model) renderConfiguredURL() string {
	label := lipgloss.NewStyle().Background(theme.ColorBackground).Bold(true).Render(m.vocab().Name + " URL")

	if m.config == nil || m.config.Forge.URL == "" {
		return label + "\n" + theme.StatusErrorStyle.Render(
			theme.IconWarning+" not configured — set it in :config, "+m.forgeTab()+" tab")
	}
	value := lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorPrimary).
		Render(m.config.Forge.URL)
	return label + "\n" + value + theme.DimStyle.Render("   change it in :config")
}

// forgeTab names the configuration tab that holds the forge settings.
//
// The tab is titled after the active forge, so this is the forge's key rather
// than a literal — the message stays true when the context targets GitHub, and
// it stayed true when the section under it was renamed from `gitlab:` to
// `forge:` (§3.6 step 4), because the *tab* is still named after the platform.
func (m Model) forgeTab() string {
	if m.config == nil || m.config.Forge.Type == "" {
		return config.ForgeGitLab
	}
	return m.config.Forge.Type
}

