18	
19	// footerInfoLine returns the last line of RenderFooter, the info line.
20	func footerInfoLine(m *Model, width int) string {
21		lines := strings.Split(m.RenderFooter(width), "\n")
22		return lines[len(lines)-1]
23	}
24	
25	func TestPostFooterMsgAppearsCenteredInTheFooter(t *testing.T) {
26		cases := []struct {
27			name  string
28			level components.Level
29			text  string
30		}{
31			{"info", components.LevelInfo, `Context "staging" created`},
32			{"warning", components.LevelWarning, "Context already active"},
33			{"error", components.LevelError, "Could not switch context"},
34		}
35		for i, tc := range cases {
36			t.Run(tc.name, func(t *testing.T) {
37				m := newTestModel(t, testConfig(), newFakeStorage())
38				const width = 100
39	
40				m = feed(t, m, components.PostFooterMsg{ID: uint64(9000 + i), Level: tc.level, Text: tc.text})
41	
42				line := footerInfoLine(m, width)
43				if !strings.Contains(line, tc.text) {
44					t.Fatalf("info line = %q, want it to carry %q", line, tc.text)
45				}
46				if got := lipgloss.Width(line); got != width {
47					t.Errorf("info line width = %d, want the full %d", got, width)
48				}
49				plain := ansi.Strip(line)
50				lead := len(plain) - len(strings.TrimLeft(plain, " "))
51				trail := len(plain) - len(strings.TrimRight(plain, " "))
52				if lead == 0 || lead-trail > 1 || trail-lead > 1 {
53					t.Errorf("message not centered: %d leading, %d trailing cells", lead, trail)
54				}
55			})
56		}
57	}
58	
59	func TestPostedFooterMessageExpires(t *testing.T) {
60		m := newTestModel(t, testConfig(), newFakeStorage())
61		const id = 9100
62	
63		m = feed(t, m, components.PostFooterMsg{ID: id, Level: components.LevelInfo, Text: "Context \"x\" created"})
64		if !strings.Contains(m.RenderFooter(100), "created") {
65			t.Fatal("message not shown before its expiry")
66		}
67	
68		// A stale expiry (another message's timer) leaves it alone.
69		m = feed(t, m, components.ClearFooterMsg{ID: id + 1})
70		if !strings.Contains(m.RenderFooter(100), "created") {
71			t.Error("a stale ClearFooterMsg removed the message")
72		}
73	
74		m = feed(t, m, components.ClearFooterMsg{ID: id})
75		if strings.Contains(m.RenderFooter(100), "created") {
76			t.Error("message still shown after its ClearFooterMsg")
77		}
78	}
79	
80	func TestFooterHeightIsUnchangedWithAMessage(t *testing.T) {
81		m := newTestModel(t, testConfig(), newFakeStorage())
82		want := m.GetFooterHeight()
83		if want != 2 {
84			t.Fatalf("GetFooterHeight() = %d, want 2 (blank line + info line)", want)
85		}
86	
87		m = feed(t, m, components.PostFooterMsg{ID: 9200, Level: components.LevelWarning, Text: "something to read"})
88	
89		if got := m.GetFooterHeight(); got != want {
90			t.Errorf("GetFooterHeight() = %d with a message, want %d", got, want)
91		}
92		if got := strings.Count(m.RenderFooter(100), "\n") + 1; got != want {
93			t.Errorf("RenderFooter() emitted %d lines with a message, want %d", got, want)
94		}
95		if !strings.Contains(footerInfoLine(m, 100), "something to read") {
96			t.Error("message is not on the info line (the last one)")
97		}
98	}
99	
100	// With no message posted, the view's own states keep showing and the footer
101	// stays two blank-looking lines.
102	func TestAuthStatesStillShowWithoutAFooterMessage(t *testing.T) {
103		m := newTestModel(t, testConfig(), newFakeStorage())
104		m = feed(t, m, AuthResultMsg{Error: errors.New("401 unauthorized")})
105	
106		if !strings.Contains(m.Render(), "401 unauthorized") {
107			t.Error("View() lost the authentication error")
108		}
109		footer := ansi.Strip(m.RenderFooter(100))
110		if strings.TrimSpace(footer) != "" {
111			t.Errorf("footer = %q, want no text when nothing was posted", footer)
112		}
113		if got := strings.Count(m.RenderFooter(100), "\n") + 1; got != m.GetFooterHeight() {
114			t.Errorf("RenderFooter() emitted %d lines, GetFooterHeight() = %d", got, m.GetFooterHeight())
115		}
116	}
